export function localizeStatic(lang){const n=['pt','en','ja'].indexOf(lang)+1;for(const [selector,...values] of staticText){document.querySelector(selector).innerHTML=values[n-1];}
 const labels=[['.inline-label',['Período ','Period ','期間 ']],['#create-fields>label',['Título','Title','タイトル']],['.form-row label:first-child',['Serviço','Service','サービス']],['.form-row label:last-child',['Impacto','Impact','影響度']],['#update-fields label',['Status','Status','ステータス']],['#message-label',['Descrição','Description','説明']]];
 for(const [selector,values] of labels)document.querySelector(selector).firstChild.textContent=values[n-1];
 const attrs=[['#search','placeholder',['Buscar título ou código','Search title or ID','タイトル・ID で検索']],['#search','aria-label',['Buscar incidentes','Search incidents','インシデントを検索']],['input[name="title"]','placeholder',['Descreva o que está acontecendo','Describe what is happening','発生している状況を入力']],['textarea','placeholder',['Registre o contexto e os próximos passos (mínimo 10 caracteres).','Describe the context and next steps (at least 10 characters).','状況と今後の対応を 10 文字以上で入力してください。']],['#close-dialog','aria-label',['Fechar','Close','閉じる']],['.summary','aria-label',['Resumo','Summary','概要']],['.tabs','aria-label',['Filtrar incidentes','Filter incidents','インシデントの絞り込み']]];
 for(const [sel,attr,values] of attrs)document.querySelector(sel).setAttribute(attr,values[n-1]);
 document.documentElement.lang=locales[lang];document.title='Service Watch · '+['Central de operações','Operations center','運用センター'][n-1];}

